export class Metadata {
  number: string;
}

export class OfferCallDto extends Metadata {
  isVideo?: boolean;
  callDuration?: number;
}

// WhatsApp Cloud API Calling (WHATSAPP-BUSINESS instances only)
export type CloudCallAction = 'pre_accept' | 'accept' | 'reject' | 'terminate';

export class CloudCallActionDto {
  callId: string;
  // SDP answer (RFC 8866) generated by the agent's WebRTC peer; required for preAccept/accept
  sdp?: string;
  // Echoed back by Meta in the terminate webhook (max 512 chars); accept only
  bizOpaqueCallbackData?: string;
}

export class CloudCallSettingsDto {
  // Passed through to Meta: POST /<PHONE_NUMBER_ID>/settings { calling: {...} }
  calling: Record<string, unknown>;
}
